"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 context at each decision point: speaker tags (dev threshold) and the situation text (plan 3.1, 6.1).

Reads the features of p1v4_feats.py (per render folder) and gives, for a meta row and point k:
  transcripts {key: Whisper-small text}, scores {key: cosine to the user's enrolment}, tags {key: "user"|"other"},
  sounds [(class, start, end, peak)], and the situation text of p1v4_situation.build in its three variants.
Speaker threshold (plan 6.1: chosen on dev, shared by all systems): the cosine cut that maximises balanced accuracy
(mean of the user and not-the-user recalls) over the unique dev speech cuts, gold = the source's speaker (user, or
visitor, TV voice, TV recording). Balanced, because user cuts outnumber the others about 15 to 1 and both errors
matter. Fixed before any system is scored.

usage: python -X utf8 scripts/p1v4_context.py threshold        (dev; writes data/p1v4/runs/spk/threshold.json)
"""
import json
import os
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_situation as SIT  # noqa: E402

FEATS = "data/p1v4/feats"
THR_PATH = "data/p1v4/runs/spk/threshold.json"


def voice_key(v):
    return json.dumps(v, sort_keys=True)


class Context:
    def __init__(self, which, final=False, threshold=None, folders=None, asr="small"):
        """asr: "small" (Whisper-small, every local system) or "turbo" (Whisper large-v3-turbo, the API rivals' situation
        text, plan 6.1; scripts/p1v4_asr_turbo.py, same speech cuts)."""
        self.segs, self.text, self.sounds, self.enrol = {}, {}, {}, {}
        emb, ids = [], []
        for name in folders or []:          # named folders go through the same lock (pre-test code review, minor 5)
            D.check_folder_name(name)
        for name in folders or D.folder_names(which, final):
            p = f"{FEATS}/{name}_"
            self.segs.update(json.load(open(p + "segs.json")))
            self.text.update(json.load(open(p + f"text_{asr}.json", encoding="utf-8")))
            self.sounds.update(json.load(open(p + "sounds.json")))
            self.enrol.update({k: np.array(v, np.float32) for k, v in json.load(open(p + "enrol.json")).items()})
            emb.append(np.load(p + "spk_emb.npy").astype(np.float32))
            ids += json.load(open(p + "spk_ids.json"))
        E = np.concatenate(emb)
        E /= np.linalg.norm(E, axis=1, keepdims=True) + 1e-9
        self.emb_row = {h: i for i, h in enumerate(ids)}
        self.E = E
        for k in self.enrol:
            self.enrol[k] /= np.linalg.norm(self.enrol[k]) + 1e-9
        if threshold is None and os.path.exists(THR_PATH):
            threshold = json.load(open(THR_PATH))["threshold"]
        self.threshold = threshold

    @staticmethod
    def pid(r, k):
        return f"{r['unit']}|{r['version']}|{k}"

    def score(self, r, h):
        return float(self.E[self.emb_row[h]] @ self.enrol[voice_key(r["spec"]["user"])])

    def point(self, r, k):
        """transcripts, scores, tags and sounds at point k of row r."""
        segs = self.segs.get(self.pid(r, k), {})
        tr = {key: self.text[h] for key, h in segs.items()}
        sc = {key: self.score(r, h) for key, h in segs.items()}
        tags = {key: ("user" if v >= self.threshold else "other") for key, v in sc.items()}
        snd = [tuple(s) for s in self.sounds.get(self.pid(r, k), [])]
        return tr, sc, tags, snd

    def situation(self, r, k, variant="full"):
        tr, _, tags, snd = self.point(r, k)
        return SIT.build(r, k, tr, tags, snd, variant)

    def ideal_situation(self, r, k):
        """The situation text with perfect perception (B2-ideal, plan 6.5): scripted words, true speakers and true
        sound labels (p1v4_situation.ideal_inputs); a real TV or radio recording keeps this context's transcript."""
        tr, _, _, _ = self.point(r, k)
        return SIT.build(r, k, *SIT.ideal_inputs(r, k, tr), "full")


def choose_threshold():
    rows = D.load_rows("dev")
    ctx = Context("dev", threshold=0.0)
    seen, scores, gold, who = set(), [], [], []
    for r in rows:
        src = {s["id"]: s for s in r["sources"]}
        for p in r["points"]:
            for key, h in ctx.segs.get(ctx.pid(r, p["k"]), {}).items():
                if (r["unit"], h) in seen:
                    continue
                seen.add((r["unit"], h))
                s = src[key.split("@")[0]]
                w = "tvfile" if s["kind"] == "tvfile" else s["who"]
                scores.append(ctx.score(r, h))
                gold.append(w == "user")
                who.append(w)
    scores, gold, who = np.array(scores), np.array(gold), np.array(who)
    cand = np.unique(np.round(scores, 3))
    best = None
    for c in cand:
        pred = scores >= c
        bal = 0.5 * (pred[gold].mean() + (~pred[~gold]).mean())
        if best is None or bal > best[0]:
            best = (float(bal), float(c))
    thr = best[1]
    pred = scores >= thr
    res = {"threshold": thr, "balanced_accuracy": best[0], "accuracy": float((pred == gold).mean()),
           "n_cuts": int(len(scores)), "rule": "max balanced accuracy over unique dev speech cuts",
           "recall_by_speaker": {w: {"n": int((who == w).sum()),
                                     "right": float((pred[who == w] == (w == "user")).mean())}
                                 for w in sorted(set(who))}}
    os.makedirs(os.path.dirname(THR_PATH), exist_ok=True)
    json.dump(res, open(THR_PATH, "w"), indent=1)
    print(json.dumps(res, indent=1))


if __name__ == "__main__":
    if sys.argv[1] == "threshold":
        choose_threshold()
    else:
        raise SystemExit(__doc__)
